invoice_runtime_secrets.py:
"""Turn native platform secret injections into private runtime files, never exports.

The infrastructure supplies secret references, not values in Terraform/source.
Platforms resolve them at startup. Rotation requires the documented workload
rollout; this module does not claim cloud-mounted files refresh automatically.
The untrusted parser never receives these values or this directory.
"""
import atexit
import os
import re
from pathlib import Path
import shutil
import tempfile

def prepare_runtime_environment(provider,environment,role):
    if provider not in {'aws','azure','gcp','ibm'}or role not in {'api','worker'}:raise ValueError('Use the owned native workload and role')
    env=dict(environment)
    if any(name in env for name in ['PARSER_SHARED_TOKEN','PARSER_SHARED_TOKEN_FILE'])and(provider!='ibm'or role!='worker'):raise ValueError('Only the IBM extraction worker receives parser admission authority')
    if 'PARSER_SHARED_TOKEN'in env and(not isinstance(env['PARSER_SHARED_TOKEN'],str)or not re.fullmatch(r'[0-9a-f]{64}',env['PARSER_SHARED_TOKEN'])):raise ValueError('Use a separately provisioned 256-bit parser token')
    if role=='api'and any(name in env for name in ['DESTINATION_TOKEN','DESTINATION_TOKEN_FILE']):raise ValueError('Do not inject outbound credentials into the API')
    if provider!='ibm'and'DATABASE_PASSWORD'in env:raise ValueError('IAM database workloads must not receive a SQL password')
    mapping={'PARSER_SHARED_TOKEN':('PARSER_SHARED_TOKEN_FILE','parser-token',64),'DATABASE_CA_PEM':('DATABASE_CA_FILE','database-ca.pem',256000),'DATABASE_PASSWORD':('DATABASE_PASSWORD_FILE','database-password',500),'DESTINATION_TOKEN':('DESTINATION_TOKEN_FILE','destination-token',16000)}
    selected=[]
    for name,(pointer,filename,maximum)in mapping.items():
        if name not in env:continue
        value=env[name]
        if pointer in env or not isinstance(value,str)or not value or len(value.encode('utf-8'))>maximum or'\0'in value:raise ValueError('Invalid or conflicting native secret injection')
        if name=='DESTINATION_TOKEN'and any(ord(c)<33 or ord(c)>126 for c in value):raise ValueError('Use the owned opaque action token')
        if name=='DATABASE_CA_PEM'and'-----BEGIN CERTIFICATE-----'not in value:raise ValueError('Use the native database CA certificate')
        selected.append((name,pointer,filename,value))
    if not selected:return env
    directory=Path(tempfile.mkdtemp(prefix='atmem-private-runtime-'));directory.chmod(0o700)
    try:
        for name,pointer,filename,value in selected:
            path=directory/filename
            # Private at creation, even under a permissive inherited umask.
            descriptor=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
            with os.fdopen(descriptor,'wb')as stream:stream.write(value.encode('utf-8'))
            env[pointer]=str(path);env.pop(name)
            if environment is os.environ:os.environ.pop(name,None)
        atexit.register(shutil.rmtree,directory,ignore_errors=True)
        return env
    except BaseException:shutil.rmtree(directory,ignore_errors=True);raise

invoice_processing.py:
"""The actual storage -> isolated parser -> model -> independent decoder composition."""
from invoice_document import DocumentError
from invoice_extraction import extract_invoice,document_evidence
from invoice_object_store import ObjectUnavailable,digest_pdf
from workflow_errors import TemporaryWork,PermanentWork
from invoice_retention import retained

class InvoiceProcessor:
    def __init__(self,objects,parser,model):
        if not callable(parser)or not callable(getattr(model,'generate',None)):raise ValueError('Use the owned parser and model adapters')
        self.objects=objects;self.parser=parser;self.model=model
    def __call__(self,row):
        if not retained(row):raise PermanentWork('Invoice retention period ended; do not read the original or call the model')
        try:
            source=row['source_ref'];raw=self.objects.load(str(row['account_id']),source)
            if digest_pdf(raw)!=source['sha256']:raise ValueError('Original identity changed')
            document=self.parser(raw);document_evidence(document)
            if document['sha256']!=source['sha256']:raise ValueError('Parsed original identity changed')
        except DocumentError:raise PermanentWork('This PDF needs review before extraction can continue')from None
        except(ObjectUnavailable,TemporaryWork):raise TemporaryWork('Original or parser temporarily unavailable')from None
        except Exception:raise PermanentWork('Original or parsed evidence could not be verified')from None
        try:return extract_invoice(document,self.model.generate)
        except(ValueError,TypeError,UnicodeError,RecursionError):raise PermanentWork('Invoice suggestions need review')from None
        except Exception:raise TemporaryWork('Model processing is temporarily unavailable')from None

invoice_parser_service.py:
"""Private bounded PDF RPC container; never expose as an anonymous public service.

Hosting must restrict callers to the worker, isolate this container and grant it
no document-store, database, model or destination permissions. Provider ingress
auth/network/TLS is a separate infrastructure boundary, not an HTTP header trust
claim made by this server. No request selects a URL, file, command or credential.
"""
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
import hashlib
import json
import os
import socket
import sys
