 'aws':COMMON+['AWS_ACCOUNT_ID','MODEL_ID','AWS_CONTAINER_CREDENTIALS_RELATIVE_URI','AWS_CONTAINER_CREDENTIALS_FULL_URI','AWS_CONTAINER_AUTHORIZATION_TOKEN_FILE','AWS_REGION','AWS_DEFAULT_REGION'],
